  on conflict (id) do update set name = excluded.name;

on conflict (id) do update set name = excluded.name, description = excluded.description, color = excluded.color,
  pattern = excluded.pattern, mode = excluded.mode, sort = excluded.sort;

on conflict (id) do update set question = excluded.question, answer = excluded.answer, type = excluded.type,
  points = excluded.points, options = excluded.options, correct_option = excluded.correct_option, updated_at = now();

-- V1.7: question difficulty (easy / medium / hard). NULL = treated as medium.
alter table public.questions add column if not exists difficulty text;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'questions_difficulty_check') then
    alter table public.questions add constraint questions_difficulty_check check (difficulty is null or difficulty in ('easy','medium','hard'));
  end if;
end $$;
create index if not exists questions_category_difficulty_idx on public.questions(category_id, difficulty);

